Method.Implementation:
 $$$TRACE("...In insertUpdatePerson method")
 Set ..Adapter.WebServiceClientClass = "EnterprisePersonService.SOAP11Endpoint"
 Set tSC = $$$OK
 Set tSC = ..Adapter.InvokeMethod("insertUpdatePerson",.patientIdElement,pRequest.Patient,pRequest.sourceSystemIdentification,pRequest.codeSystem,.warnings)
 $$$TRACE("...In insertUpdatePerson method .. Status.."_tSC)  
 if ('tSC){
     	set errText = $System.Status.GetErrorText(tSC)
     	$$$TRACE("...In insertUpdatePerson method .. "_errText) 
     	If $ZERROR["<ZSOAP>" {
	     	$$$TRACE("... Has SOAP Fault ...")
	     	set faultErrTxt = $System.Status.GetErrorText(%objlasterror)
	     	If faultErrTxt["ERROR #6248:"{	
      			$$$TRACE(" ### ERROR #6248 ")
      			if faultErrTxt["INITIATE_EINVAL" {  //InputDataError in BPL process
	      			set tSC = $$$ERROR(6248," ERROR: "_faultErrTxt)
	      			Quit tSC
     	    	}
     	    	if faultErrTxt["INITIATE_ESTATUS" {
	      			set tSC = $$$ERROR(6248," ERROR: "_faultErrTxt)
	      			Quit tSC
     	    	}     	
     	    	If faultErrTxt["INITIATE_EEXISTS" {
			       $$$TRACE("...In insertUpdatePerson method .. SKIPPING the RECORD.."_faultErrTxt)
			       set status = ##class(IHC.ITF.ITFCOMMON.Utility).SkipMsgError("Out-Initiate-Demogr-Xml-Soap-FROMCERN", faultErrTxt)                                 
			       Quit $$$OK
		        }
      		}     
      		If faultErrTxt["ERROR #6059:"{	//Retry and disable in operation
     	    	throw $$$ERROR(6059," Error while communicationg with Initiate server: "_faultErrTxt)     	    
     		} 	
     		If faultErrTxt["ERROR #6242:"{	
    		  $$$TRACE("...In insertUpdatePerson method. ERROR #6242 ")
      		  set tSC =  $$$ERROR(6242," Error while communicationg with Initiate server: "_faultErrTxt)                                 	          	    
   			}	     	     	          
     	}else{ // Regular exception
	     	set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).ItfGeneralError("Out-Initiate-Demogr-Xml-Soap-FROMCERN",errText)
     	    Quit tSC
	    }
 }else{
	 Set tSC = pRequest.NewResponse(.pResponse)  Quit:$$$ISERR(tSC) tSC 
  	 Set pResponse.patientIdElement=$get(patientIdElement),pResponse.warnings = $get(warnings)
     if ($length(pResponse.patientIdElement) > 0){
		 $$$TRACE("...Patient MRN: "_pResponse.patientIdElement)
	 }else{
	 	 set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).ItfGeneralError("Out-Initiate-Demogr-Xml-Soap-FROMCERN", "Unknown error while calling the InsertAddUpdate Initiate Webservice Operation")                                
	 	 Quit tSC 	 
 	 }
 }
 Quit tSC

   $$$TRACE("...In mergePerson method")
   Set ..Adapter.WebServiceClientClass = "EnterprisePersonService.SOAP11Endpoint"
